    {
      "path": "src/extract/data_extractor.py",
      "content": "\"\"\"PySpark Data Extractor - Migrated from ABAP zcl_etl_extractor.\"\"\"\n\nfrom pyspark.sql import SparkSession, DataFrame\nfrom pyspark.sql import functions as F\nfrom pyspark.sql.types import (\n    StructType, StructField, StringType, DecimalType, TimestampType\n)\nfrom typing import Optional, Dict, Any\nfrom datetime import datetime\nimport logging\n\nfrom src.utils.logger import ETLLogger\nfrom src.config.config_manager import ConfigManager\n\n\nclass DataExtractor:\n    \"\"\"Extracts data from various sources using PySpark DataFrame API.\"\"\"\n\n    def __init__(self, spark: SparkSession, source_type: str = \"DATABASE\", run_id: str = \"\"):\n        \"\"\"Initialize the data extractor.\n        \n        Args:\n            spark: SparkSession instance\n            source_type: Type of data source (DATABASE, STAGING, INCREMENTAL)\n            run_id: Unique identifier for this ETL run\n        \"\"\"\n        self.spark = spark\n        self.source_type = source_type or \"DATABASE\"\n        self.run_id = run_id\n        self.logger = ETLLogger.get_instance()\n        self.config = ConfigManager.get_instance()\n        \n    @staticmethod\n    def get_source_schema() -> StructType:\n        \"\"\"Define the schema for source data.\n        \n        Returns:\n            StructType: Schema definition for source records\n        \"\"\"\n        return StructType([\n            StructField(\"id\", StringType(), False),\n            StructField(\"name\", StringType(), True),\n            StructField(\"value\", DecimalType(15, 2), True),\n            StructField(\"status\", StringType(), True),\n            StructField(\"category\", StringType(), True),\n            StructField(\"source_system\", StringType(), True),\n            StructField(\"created_at\", TimestampType(), True),\n            StructField(\"created_by\", StringType(), True),\n            StructField(\"changed_at\", TimestampType(), True),\n            StructField(\"changed_by\", StringType(), True)\n        ])\n\n    def extract_data(\n        self,\n        filter_condition: Optional[str] = None,\n        max_records: int = 0\n    ) -> DataFrame:\n        \"\"\"Extract data based on configured source type.\n        \n        Args:\n            filter_condition: Optional SQL filter condition\n            max_records: Maximum number of records to extract (0 = unlimited)\n            \n        Returns:\n            DataFrame: Extracted data\n            \n        Raises:\n            Exception: If extraction fails\n        \"\"\"\n        self.logger.log_info(\n            component=\"EXTRACTOR\",\n            message=f\"Starting extraction - Source: {self.source_type}\"\n        )\n        \n        try:\n            if self.source_type == \"DATABASE\":\n                df = self._extract_from_database(filter_condition)\n            elif self.source_type == \"STAGING\":\n                df = self._extract_from_staging(self.run_id)\n            elif self.source_type == \"INCREMENTAL\":\n                df = self._extract_incremental()\n            else:\n                df = self._extract_from_database(filter_condition)\n            \n            # Apply max records limit if specified\n            if max_records > 0:\n                df = df.limit(max_records)\n            \n            record_count = df.count()\n            self.logger.log_info(\n                component=\"EXTRACTOR\",\n                message=f\"Extracted {record_count} records\"\n            )\n            \n            return df\n            \n        except Exception as e:\n            self.logger.log_error(\n                component=\"EXTRACTOR\",\n                message=\"Extraction failed\",\n                details=str(e)\n            )\n            raise\n\n    def _extract_from_database(self, filter_condition: Optional[str] = None) -> DataFrame:\n        \"\"\"Extract data from database source.\n        \n        Args:\n            filter_condition: Optional SQL WHERE clause condition\n            \n        Returns:\n            DataFrame: Extracted records\n        \"\"\"\n        table_name = self.config.get_config(\"source_table\", \"zetl_source_data\")\n        \n        # Read from database table\n        df = self.spark.read \\\n            .format(\"jdbc\") \\\n            .option(\"url\", self.config.get_config(\"jdbc_url\")) \\\n            .option(\"dbtable\", table_name) \\\n            .option(\"user\", self.config.get_config(\"db_user\")) \\\n            .option(\"password\", self.config.get_config(\"db_password\")) \\\n            .option(\"driver\", self.config.get_config(\"jdbc_driver\", \"org.postgresql.Driver\")) \\\n            .load()\n        \n        # Apply filter if provided\n        if filter_condition:\n            df = df.filter(filter_condition)\n        \n        # Apply default limit for safety\n        max_rows = self.config.get_config(\"default_extract_limit\", 1000)\n        df = df.limit(max_rows)\n        \n        return df\n\n    def _extract_from_staging(self, run_id: str) -> DataFrame:\n        \"\"\"Extract data from staging area.\n        \n        Args:\n            run_id: Run ID to filter staging records\n            \n        Returns:\n            DataFrame: Staged records ready for processing\n        \"\"\"\n        staging_table = self.config.get_config(\"staging_table\", \"zetl_staging\")\n        \n        df = self.spark.read \\\n            .format(\"jdbc\") \\\n            .option(\"url\", self.config.get_config(\"jdbc_url\")) \\\n            .option(\"dbtable\", staging_table) \\\n            .option(\"user\", self.config.get_config(\"db_user\")) \\\n            .option(\"password\", self.config.get_config(\"db_password\")) \\\n            .load() \\\n            .filter(F.col(\"run_id\") == run_id) \\\n            .filter(F.col(\"status\") == \"READY\")\n        \n        # Transform staged data to source schema\n        df = df.select(\n            F.col(\"id\"),\n            F.lit(\"STAGED\").alias(\"status\")\n        )\n        \n        return df\n\n    def _extract_incremental(self) -> DataFrame:\n        \"\"\"Extract only changed records since last successful run.\n        \n        Returns:\n            DataFrame: Incrementally changed records\n        \"\"\"\n        # Get last successful run time\n        run_log_table = self.config.get_config(\"run_log_table\", \"zetl_run_log\")\n        \n        last_run_df = self.spark.read \\\n            .format(\"jdbc\") \\\n            .option(\"url\", self.config.get_config(\"jdbc_url\")) \\\n            .option(\"dbtable\", run_log_table) \\\n            .option(\"user\", self.config.get_config(\"db_user\")) \\\n            .option(\"password\", self.config.get_config(\"db_password\")) \\\n            .load() \\\n            .filter(F.col(\"status\") == \"SUCCESS\") \\\n            .orderBy(F.col(\"end_time\").desc()) \\\n            .limit(1)\n        \n        if last_run_df.count() == 0:\n            # No previous successful run - do full extract\n            self.logger.log_info(\n                component=\"EXTRACTOR\",\n                message=\"No previous successful run found - performing full extraction\"\n            )\n            return self._extract_from_database()\n        \n        last_run_time = last_run_df.select(\"end_time\").first()[0]\n        \n        # Extract changed records\n        source_table = self.config.get_config(\"source_table\", \"zetl_source_data\")\n        \n        df = self.spark.read \\\n            .format(\"jdbc\") \\\n            .option(\"url\", self.config.get_config(\"jdbc_url\")) \\\n            .option(\"dbtable\", source_table) \\\n            .option(\"user\", self.config.get_config(\"db_user\")) \\\n            .option(\"password\", self.config.get_config(\"db_password\")) \\\n            .load() \\\n            .filter(F.col(\"changed_at\") > last_run_time)\n        \n        record_count = df.count()\n        self.logger.log_info(\n            component=\"EXTRACTOR\",\n            message=f\"Incremental extraction: {record_count} changed records\"\n        )\n        \n        return df\n",
      "language": "python",
      "description": "Data extraction module using PySpark DataFrame API for reading from multiple sources"
    },
    {
      "path": "src/transform/data_transformer.py",
      "content": "\"\"\"PySpark Data Transformer - Migrated from ABAP zcl_etl_transformer.\"\"\"\n\nfrom pyspark.sql import SparkSession, DataFrame\nfrom pyspark.sql import functions as F\nfrom pyspark.sql.types import (\n    StructType, StructField, StringType, DecimalType, \n    TimestampType, IntegerType\n)\nfrom typing import List, Tuple, Dict, Any\nfrom datetime import datetime\n\nfrom src.utils.logger import ETLLogger\nfrom src.config.config_manager import ConfigManager\n\n\nclass DataTransformer:\n    \"\"\"Transforms data using PySpark DataFrame operations.\"\"\"\n\n    def __init__(self, spark: SparkSession, run_id: str):\n        \"\"\"Initialize the data transformer.\n        \n        Args:\n            spark: SparkSession instance\n            run_id: Unique identifier for this ETL run\n        \"\"\"\n        self.spark = spark\n        self.run_id = run_id\n        self.logger = ETLLogger.get_instance()\n        self.config = ConfigManager.get_instance()\n\n    @staticmethod\n    def get_transformed_schema() -> StructType:\n        \"\"\"Define the schema for transformed data.\n        \n        Returns:\n            StructType: Schema definition for transformed records\n        \"\"\"\n        return StructType([\n            StructField(\"id\", StringType(), False),\n            StructField(\"name\", StringType(), True),\n            StructField(\"value\", DecimalType(15, 2), True),\n            StructField(\"transformed_value\", DecimalType(15, 2), True),\n            StructField(\"status\", StringType(), True),\n            StructField(\"category\", StringType(), True),\n            StructField(\"priority\", IntegerType(), True),\n            StructField(\"etl_run_id\", StringType(), True),\n            StructField(\"processed_at\", TimestampType(), True),\n            StructField(\"processed_by\", StringType(), True)\n        ])\n\n    def transform_data(self, source_df: DataFrame) -> DataFrame:\n        \"\"\"Apply transformations to source data.\n        \n        Args:\n            source_df: Source DataFrame to transform\n            \n        Returns:\n            DataFrame: Transformed data\n        \"\"\"\n        self.logger.log_info(\n            component=\"TRANSFORMER\",\n            message=\"Starting transformation\"\n        )\n        \n        current_timestamp = datetime.now()\n        current_user = self.config.get_config(\"current_user\", \"system\")\n        \n        # Apply transformations using DataFrame operations\n        df = source_df.select(\n            F.col(\"id\"),\n            # Normalize name: uppercase and trim\n            F.upper(F.trim(F.regexp_replace(F.col(\"name\"), \"\\\\s+\", \" \"))).alias(\"name\"),\n            F.col(\"value\"),\n            # Calculate transformed value based on category\n            self._calculate_derived_value_udf(F.col(\"value\"), F.col(\"category\")).alias(\"transformed_value\"),\n            F.lit(\"TRANSFORMED\").alias(\"status\"),\n            F.col(\"category\"),\n            # Calculate priority\n            self._calculate_priority_udf(F.col(\"value\"), F.col(\"category\")).alias(\"priority\"),\n            F.lit(self.run_id).alias(\"etl_run_id\"),\n            F.lit(current_timestamp).alias(\"processed_at\"),\n            F.lit(current_user).alias(\"processed_by\")\n        )\n        \n        # Apply category-specific rules\n        df = self._apply_category_rules(df)\n        \n        # Apply business rules\n        df = self._apply_business_rules(df)\n        \n        # Enrich data\n        df = self._enrich_data(df)\n        \n        record_count = df.count()\n        self.logger.log_info(\n            component=\"TRANSFORMER\",\n            message=f\"Transformed {record_count} records\"\n        )\n        \n        return df\n\n    def _calculate_derived_value_udf(self, value_col, category_col):\n        \"\"\"Calculate derived/transformed value based on category.\n        \n        Args:\n            value_col: Value column\n            category_col: Category column\n            \n        Returns:\n            Column: Transformed value calculation\n        \"\"\"\n        return F.when(category_col == \"PREMIUM\", value_col * 1.5) \\\n            .when(category_col == \"STANDARD\", value_col * 1.2) \\\n            .when(category_col == \"BASIC\", value_col * 1.0) \\\n            .otherwise(value_col * 1.1)\n\n    def _calculate_priority_udf(self, value_col, category_col):\n        \"\"\"Calculate priority based on value and category.\n        \n        Args:\n            value_col: Value column\n            category_col: Category column\n            \n        Returns:\n            Column: Priority calculation (1=highest, 5=lowest)\n        \"\"\"\n        base_priority = F.when(value_col >= 500, 1) \\\n            .when(value_col >= 300, 2) \\\n            .when(value_col >= 100, 3) \\\n            .otherwise(4)\n        \n        # Adjust for premium category\n        return F.when(\n            category_col == \"PREMIUM\",\n            F.when(base_priority - 1 < 1, 1).otherwise(base_priority - 1)\n        ).otherwise(base_priority)\n\n    def _apply_category_rules(self, df: DataFrame) -> DataFrame:\n        \"\"\"Apply category-specific transformation rules.\n        \n        Args:\n            df: DataFrame to transform\n            \n        Returns:\n            DataFrame: Transformed DataFrame\n        \"\"\"\n        df = df.withColumn(\n            \"status\",\n            F.when(F.col(\"category\") == \"PREMIUM\", \"PREMIUM_PROCESSED\")\n            .when(F.col(\"category\") == \"VIP\", \"VIP_PROCESSED\")\n            .otherwise(F.col(\"status\"))\n        )\n        \n        return df\n\n    def _apply_business_rules(self, df: DataFrame) -> DataFrame:\n        \"\"\"Apply business transformation rules.\n        \n        Args:\n            df: DataFrame to transform\n            \n        Returns:\n            DataFrame: Transformed DataFrame\n        \"\"\"\n        self.logger.log_info(\n            component=\"TRANSFORMER\",\n            message=\"Applying business rules\"\n        )\n        \n        # Rule 1: Set status based on value\n        df = df.withColumn(\n            \"status\",\n            F.when(F.col(\"value\").isNull(), \"INVALID\")\n            .when(F.col(\"transformed_value\") >= 750, \"HIGH_VALUE\")\n            .when(F.col(\"transformed_value\") >= 300, \"MEDIUM_VALUE\")\n            .otherwise(\"LOW_VALUE\")\n        )\n        \n        # Rule 2: Priority override for high value items\n        df = df.withColumn(\n            \"priority\",\n            F.when(F.col(\"transformed_value\") >= 1000, 1)\n            .otherwise(F.col(\"priority\"))\n        )\n        \n        # Rule 3: Category validation\n        df = df.withColumn(\n            \"category\",\n            F.when(\n                F.col(\"category\").isNull() | (F.col(\"category\") == \"\"),\n                \"UNCATEGORIZED\"\n            ).otherwise(F.col(\"category\"))\n        )\n        \n        return df\n\n    def _enrich_data(self, df: DataFrame) -> DataFrame:\n        \"\"\"Enrich data with additional information.\n        \n        Args:\n            df: DataFrame to enrich\n            \n        Returns:\n            DataFrame: Enriched DataFrame\n        \"\"\"\n        # Load enrichment configuration\n        config_table = self.config.get_config(\"config_table\", \"zetl_config\")\n        \n        try:\n            config_df = self.spark.read \\\n                .format(\"jdbc\") \\\n                .option(\"url\", self.config.get_config(\"jdbc_url\")) \\\n                .option(\"dbtable\", config_table) \\\n                .option(\"user\", self.config.get_config(\"db_user\")) \\\n                .option(\"password\", self.config.get_config(\"db_password\")) \\\n                .load() \\\n                .filter(F.col(\"is_active\") == \"X\")\n            \n            # Apply premium enrichment based on config\n            premium_multiplier = config_df \\\n                .filter(F.col(\"config_key\") == \"PREMIUM_MULTIPLIER\") \\\n                .select(\"config_value\") \\\n                .first()\n            \n            if premium_multiplier:\n                multiplier = float(premium_multiplier[0])\n                df = df.withColumn(\n                    \"transformed_value\",\n                    F.when(\n                        F.col(\"category\") == \"PREMIUM\",\n                        F.col(\"transformed_value\") * multiplier\n                    ).otherwise(F.col(\"transformed_value\"))\n                )\n        except Exception as e:\n            self.logger.log_warning(\n                component=\"TRANSFORMER\",\n                message=\"Failed to load enrichment config\",\n                details=str(e)\n            )\n        \n        return df\n\n    def validate_data(self, df: DataFrame) -> Tuple[bool, List[str]]:\n        \"\"\"Validate transformed data.\n        \n        Args:\n            df: DataFrame to validate\n            \n        Returns:\n            Tuple[bool, List[str]]: (is_valid, list of validation errors)\n        \"\"\"\n        errors = []\n        \n        # Validation rule 1: ID is required\n        null_ids = df.filter(F.col(\"id\").isNull() | (F.col(\"id\") == \"\")).count()\n        if null_ids > 0:\n            errors.append(f\"{null_ids} records with missing ID\")\n        \n        # Validation rule 2: Name is required\n        null_names = df.filter(F.col(\"name\").isNull() | (F.col(\"name\") == \"\")).count()\n        if null_names > 0:\n            errors.append(f\"{null_names} records with missing name\")\n        \n        # Validation rule 3: Value must be positive\n        negative_values = df.filter(F.col(\"value\") < 0).count()\n        if negative_values > 0:\n            errors.append(f\"{negative_values} records with negative values\")\n        \n        # Validation rule 4: Priority must be 1-5\n        invalid_priority = df.filter(\n            (F.col(\"priority\") < 1) | (F.col(\"priority\") > 5)\n        ).count()\n        if invalid_priority > 0:\n            errors.append(f\"{invalid_priority} records with invalid priority\")\n        \n        # Validation rule 5: Check for duplicates\n        total_count = df.count()\n        unique_count = df.select(\"id\").distinct().count()\n        if total_count != unique_count:\n            errors.append(f\"{total_count - unique_count} duplicate IDs found\")\n        \n        is_valid = len(errors) == 0\n        \n        if not is_valid:\n            self.logger.log_warning(\n                component=\"TRANSFORMER\",\n                message=f\"Validation failed: {len(errors)} errors found\"\n            )\n        \n        return is_valid, errors\n",
      "language": "python",
      "description": "Data transformation module with business rules and validation using PySpark DataFrame operations"
    },
